public int subsetXORSum(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        int xor = 0;
        for (int j = 0; j < n; j++) {
            if ((mask & (1 << j)) != 0) {
                xor ^= nums[j];
            }
        }
        sum += xor;
    }
    return sum;
}

code.python:
def subsetXORSum(self, nums: list[int]) -> int:
    n = len(nums)
    total = 0
    for mask in range(1 << n):
        xor = 0
        for j in range(n):
            if mask & (1 << j):
                xor ^= nums[j]
        total += xor
    return total

code.java:
public int subsetXORSum(int[] nums) {
    int orAll = 0;
    for (int x : nums) {
        orAll |= x;
    }
    return orAll << (nums.length - 1);
}

